 public static function prepare(User $actor,int $auth,array $request,string $expected,string $token,string $reason,bool $staffChecked=false):Run {
  if(!Str::isUuid($token)||mb_strlen(trim($reason))<5||mb_strlen($reason)>1000)CentrePlanning::fail('Use a fresh request and a clear arrangements reference.');
  return DB::transaction(function()use($actor,$auth,$request,$expected,$token,$reason,$staffChecked){$u=PortalActions::actor(CentrePlanning::actor($actor,$auth));$d=self::input($request);if($d['staff_options']&&!$staffChecked)CentrePlanning::fail('Confirm the nominated staff are suitable and the allocation is agreed.');$old=Run::where('request_token',$token)->lockForUpdate()->first();if($old){if(TimetableOptimiser::intact($old)&&$old->created_by===$u->id&&$old->details['auth']===$auth&&($old->details['preview']['request']??null)===$d&&$old->source_hash===$expected&&$old->details['reason']===$reason&&($old->details['staff_suitability_checked']??false)===$staffChecked)return$old;CentrePlanning::fail('Request belongs to different or damaged work.');}$v=self::preview($u,$d,true);if(!hash_equals($expected,$v['source_hash'])||!$v['can_apply'])CentrePlanning::fail('Source changed or no checked improvement remains. Reopen the preview.');$r=new Run(['id'=>(string)Str::uuid(),'request_token'=>$token,'created_by'=>$u->id,'source_hash'=>$expected,'state'=>'Prepared','version'=>1]);$r->details=['fields'=>$r->only(['id','request_token','created_by','source_hash']),'auth'=>$auth,'reason'=>$reason,'staff_suitability_checked'=>$staffChecked,'preview'=>$v,'expires'=>now()->addMinutes(30)->toIso8601String()];$r->details_hash=ReviewedImports::hash($r->details);$r->save();CentrePlanning::event($u,'annual_prepared',1,['run'=>$r->id,'source_hash'=>$expected,'reservations_changed'=>false]);return$r;},3);
 }
