  return DB::transaction(function()use($actor,$auth,$record,$version,$expected,$warningsAccepted){$u=PortalActions::actor(CentrePlanning::actor($actor,$auth));$r=Run::whereKey($record->id)->lockForUpdate()->firstOrFail();abort_unless($r->created_by===$u->id,403);if(!TimetableOptimiser::intact($r)||$r->details['auth']!==$auth||$r->details_hash!==$expected||$version!==1||($r->details['preview']['mode']??null)!=='annual54')CentrePlanning::fail('The proposal, account or source changed.');
   if($r->state==='Applied'){foreach($r->receipt['replacements']as$id){$p=Plan::findOrFail($id);TimetableGovernance::guardPlan($u,$p);if($p->state!=='Published'||!CentrePlanning::published($p))CentrePlanning::fail('A recorded replacement changed. Inspect its retained history.');}return$r;}
   if($r->state!=='Prepared'||Carbon::parse($r->details['expires'])->lte(now()))CentrePlanning::fail('Proposal closed or expired. Prepare a new preview.');$saved=$r->details['preview'];$current=self::preview($u,$saved['request'],true);if($current['source_hash']!==$r->source_hash||$current['suggestion']!==$saved['suggestion']||!$current['can_apply']||$current['warnings']&&!$warningsAccepted)CentrePlanning::fail('Source, choices, access or warnings changed. Nothing was moved.');
   $changed=array_filter($saved['suggestion'],fn($s)=>$s['changed']);$new=[];foreach($changed as$id=>$s){$old=Plan::whereKey($id)->lockForUpdate()->firstOrFail();CentrePlanning::withdraw($u,$auth,$old,$old->version,'Reviewed annual plan: '.$r->details['reason']);}
   foreach($changed as$id=>$s){$p=CentrePlanning::save($u,$auth,null,0,(string)Str::uuid(),$s['after']);$new[$id]=$p->id;}
   foreach($new as$id=>$replacement){$p=Plan::findOrFail($replacement);CentrePlanning::check($u,$auth,$p,1,$warningsAccepted);CentrePlanning::publish($u,$auth,$p->refresh(),2);$control=TimetableAllocationControl::whereKey($id)->lockForUpdate()->first();if($control&&($control->restricted||$control->ceo_locked)){TimetableGovernance::allocation($u,$auth,$p->refresh(),0,TimetableGovernanceState::findOrFail(1)->revision,$control->restricted,$control->ceo_locked,'Protection retained from annual source '.$id); }CentrePlanning::event($u,'annual_replacement',$p->refresh()->version,['run'=>$r->id,'original'=>$id,'replacement'=>$replacement,'before'=>$saved['suggestion'][$id]['before'],'after'=>$saved['suggestion'][$id]['after'],'minutes_and_occurrence_count_preserved'=>true],$p);}
